# ===================== L208 statistics =====================
def side_stats(raw, arm, seed, pk, mask):
    """Pool-mean saturation statistics per side over `mask` steps."""
    ag, bg = PREF[pk]
    out = {}
    for side in ("L", "R"):
        cols = [raw[f"{pk}_{ag}{side}_{arm}_{seed}"][:WIN][mask],
                raw[f"{pk}_{bg}{side}_{arm}_{seed}"][:WIN][mask]]
        v = np.concatenate(cols).astype(np.float64)
        out[side] = dict(
            lvl=float(v.mean()),
            margin=float(RMAX - v.mean()),
            fhi95=float((v >= 0.95).mean()),
            fhi90=float((v >= 0.90).mean()),
            flo=float((v <= BG).mean()),
            pmax=float(v.max()),
        )
    return out


def spearman(x, y):
    rx = np.argsort(np.argsort(x)).astype(np.float64)
    ry = np.argsort(np.argsort(y)).astype(np.float64)
    rx -= rx.mean()
    ry -= ry.mean()
    den = math.sqrt(float((rx * rx).sum()) * float((ry * ry).sum()))
    return float((rx * ry).sum() / den) if den > 0 else float("nan")


